-- Explicit reviewed snapshot for litigation_diego_morales_47/delivery_logistics; no runtime content generator.
CREATE TEMP TABLE _seed_carriers (carrier_key TEXT PRIMARY KEY, carrier_value TEXT NOT NULL);
CREATE TEMP TABLE _seed_event_times (time_key TEXT PRIMARY KEY, status_event_at TEXT NOT NULL);
CREATE TEMP TABLE _seed_service_levels (service_key TEXT PRIMARY KEY, service_value TEXT NOT NULL);
DROP TABLE _seed_carriers;
DROP TABLE _seed_service_levels;
DROP TABLE _seed_event_times;

-- 2026-08-02 quality repair: reviewed in-place rewrites for status-consistent, non-template operational events.
CREATE TEMP TABLE _quality_event_rewrite (target_rowid INTEGER PRIMARY KEY, revised_description TEXT NOT NULL);
UPDATE shipment_events
SET description = (SELECT revised_description FROM _quality_event_rewrite q WHERE q.target_rowid = shipment_events.rowid)
WHERE rowid IN (SELECT target_rowid FROM _quality_event_rewrite);
DROP TABLE _quality_event_rewrite;

